package fr.univartois.butinfo.fractalens.image.color;

import java.awt.*;

/**
 * The {@code ColoredInverse} class represents a color decorator strategy
 * that inverts the colors generated by an underlying color strategy (producing complementary colors).
 *
 * @author Eva Nys
 *
 * @version 0.1.0
 */
public class ColoredInverse implements IColor {

    /**
     * The underlying color strategy being decorated.
     */
    private final IColor decor;
    /**
     * Constructs a new {@code ColoredInverse} decorating the specified color strategy.
     *
     * @param decor The underlying color strategy to decorate.
     */
    public ColoredInverse(IColor decor) {
        this.decor = decor;
    }



    /**
     * Determines the color of a pixel by obtaining the color from the decorated strategy
     * and returning its complementary (inverted) color.
     *
     * @param iteration The iteration count for the pixel.
     * @param max       The maximum number of iterations.
     * @return The inverted {@link Color} for the pixel.
     */
    @Override
    public Color coloredDot(int iteration, int max) {
        Color palette = decor.coloredDot(iteration, max);
        int r = palette.getRed();
        int g = palette.getGreen();
        int b = palette.getBlue();

        int complementaryR = 255 - r;
        int complementaryG = 255 - g;
        int complementaryB = 255 - b;
        return new Color(complementaryR, complementaryG, complementaryB);
    }
}
